{"version":"v0.9","updateComponents":{"surfaceId":"surface_card","root":"root","components":[{"id":"root","component":"Row","children":["album_panel","side_panel"],"itemMargin":8,"styles":{"width":300,"height":140,"padding":12,"borderRadius":22,"clip":true,"linearGradient":{"direction":"RightBottom","colors":[["#5f58c7",0],["#467794",1]]},"alignItems":"center"}},{"id":"album_panel","component":"Column","children":["album_title","album_check_row","album_count"],"itemMargin":8,"styles":{"width":140,"height":116,"padding":10,"borderRadius":18,"backgroundColor":"#19ffffff","justifyContent":"center","alignItems":"start"}},{"id":"album_title","component":"Text","content":"{{ ${/selection/photoTitle} }}","styles":{"width":120,"height":20,"fontSize":16,"fontWeight":700,"fontColor":"#ffffffff","maxLines":1,"textOverflow":"none"}},{"id":"album_check_row","component":"Row","children":["photo_checkbox","photo_state"],"itemMargin":8,"styles":{"width":120,"height":32,"alignItems":"center","justifyContent":"start"}},{"id":"photo_checkbox","component":"Checkbox","label":"","value":"photo-main","group":"album","select":"{{ ${/selection/photoSelected} }}","styles":{"width":24,"height":24,"shape":"rounded_square","selectedColor":"#64bb5c","unSelectedColor":"#99ffffff","mark":{"strokeColor":"#ffffffff","size":16,"strokeWidth":2}}},{"id":"photo_state","component":"Text","content":"{{ ${/selection/photoSelected} ? '已勾选照片' : '选择照片' }}","styles":{"width":88,"height":18,"fontSize":14,"fontWeight":500,"fontColor":"#e5ffffff","maxLines":1,"textOverflow":"none"}},{"id":"album_count","component":"Text","content":"{{ ${/selection/photoCountText} }}","styles":{"width":120,"height":16,"fontSize":12,"fontWeight":400,"fontColor":"#99ffffff","maxLines":1,"textOverflow":"none"}},{"id":"side_panel","component":"Column","children":["weather_row","air_text","call_button"],"itemMargin":6,"styles":{"width":128,"height":116,"padding":6,"borderRadius":18,"backgroundColor":"#0cffffff","justifyContent":"center","alignItems":"start"}},{"id":"weather_row","component":"Row","children":["weather_icon","weather_texts"],"itemMargin":6,"styles":{"width":116,"height":38,"alignItems":"center","justifyContent":"start"}},{"id":"weather_icon","component":"Image","src":"resources/base/media/cloudy.png","styles":{"width":32,"height":32,"objectFit":"contain"}},{"id":"weather_texts","component":"Column","children":["temperature_text","condition_text"],"itemMargin":2,"styles":{"width":78,"height":36,"justifyContent":"center","alignItems":"start"}},{"id":"temperature_text","component":"Text","content":"{{ ${/data/weather/current/temperatureText} }}","styles":{"width":78,"height":20,"fontSize":18,"fontWeight":700,"fontColor":"#ffffffff","maxLines":1,"textOverflow":"none"}},{"id":"condition_text","component":"Text","content":"{{ ${/data/weather/location/districtName} + ' ' + ${/data/weather/current/condition} }}","styles":{"width":78,"height":14,"fontSize":12,"fontWeight":400,"fontColor":"#99ffffff","maxLines":1,"textOverflow":"none"}},{"id":"air_text","component":"Text","content":"{{ '空气 ' + ${/data/weather/current/airQuality} }}","styles":{"width":116,"height":14,"fontSize":12,"fontWeight":400,"fontColor":"#99ffffff","maxLines":1,"textOverflow":"none"}},{"id":"call_button","component":"Button","label":"打电话","onClick":[{"call":"clickToCallPhone","args":{"phoneNumber":"4008001234"}}],"styles":{"width":96,"height":32,"borderRadius":16,"backgroundColor":"#ff64bb5c","fontSize":14,"fontWeight":500,"fontColor":"#ffffffff"}}]}}
